package ai.areas.FaeronVillage.RemembranceTower;

import org.l2jmobius.gameserver.entity.actor.Npc;
import org.l2jmobius.gameserver.entity.actor.Player;
import org.l2jmobius.gameserver.mechanics.script.Script;
import org.l2jmobius.gameserver.network.serverpackets.OnEventTrigger;

/**
 * Handles the artificial intelligence for the {@code RemembranceTower} area.<br>
 * This class manages specific behaviors and interactions for NPCs within this location.
 * @author St3eT
 */
public class RemembranceTower extends Script
{
	// NPCs
	private static final int REMEMBRANCE_TOWER = 33989;
	
	// Misc
	private static final int EMMITER_ID = 17250700;
	
	/**
	 * Private constructor for the {@code RemembranceTower} class.<br>
	 * This prevents other classes from creating new instances of this script.<br>
	 * It initializes the required NPC IDs and talk triggers.
	 */
	private RemembranceTower()
	{
		addStartNpc(REMEMBRANCE_TOWER);
		addTalkId(REMEMBRANCE_TOWER);
		addFirstTalkId(REMEMBRANCE_TOWER);
	}
	
	/**
	 * Handles specific events for the Remembrance Tower script.<br>
	 * It manages actions and triggers related to the emitter.
	 * @param event The name of the event being triggered.
	 * @param npc The {@code Npc} instance involved in the event.
	 * @param player The {@code Player} instance interacting with the NPC.
	 * @return The result of the super class {@code onEvent} method.
	 */
	@Override
	public String onEvent(String event, Npc npc, Player player)
	{
		if (event.equals("action") && npc.isScriptValue(0))
		{
			npc.broadcastPacket(new OnEventTrigger(EMMITER_ID, true));
			npc.setScriptValue(1);
			startQuestTimer("TRIGGER", 3000, npc, null);
		}
		else if (event.equals("TRIGGER"))
		{
			npc.setScriptValue(0);
			npc.broadcastPacket(new OnEventTrigger(EMMITER_ID, false));
		}
		
		return super.onEvent(event, npc, player);
	}
	
	/**
	 * This method handles the first interaction between a {@code Player} and an {@code Npc}.<br>
	 * It determines which dialogue file to display based on the NPC's ID.
	 * @param npc The {@code Npc} that is being interacted with.
	 * @param player The {@code Player} who initiated the conversation.
	 * @return A {@code String} representing the path to the HTML dialogue file.
	 */
	@Override
	public String onFirstTalk(Npc npc, Player player)
	{
		return npc.getId() + ".html";
	}
	
	/**
	 * This is the entry point for the {@code RemembranceTower} class.<br>
	 * It initializes a new instance of the script.
	 * @param args Command line arguments passed to the program.
	 */
	public static void main(String[] args)
	{
		new RemembranceTower();
	}
}
